INSERT INTO DimCompany (SK_CompanyID, CompanyID, Status, Name, Industry, SPrating, isLowGrade, CEO, Description, FoundingDate, AddressLine1, AddressLine2, PostalCode, City, StateProv, Country, IsCurrent, BatchID, EffectiveDate, EndDate) SELECT CAST(ROW_NUMBER() OVER (ORDER BY CompanyID, EffectiveDate) AS INT) AS SK_CompanyID, CAST(CompanyID AS INT) AS CompanyID, CAST(Status AS TEXT) AS Status, CAST(Name AS TEXT) AS Name, CAST(Industry AS TEXT) AS Industry, CAST(SPrating AS TEXT) AS SPrating, CAST(isLowGrade AS BOOLEAN) AS isLowGrade, CAST(CEO AS TEXT) AS CEO, CAST(Description AS TEXT) AS Description, CAST(FoundingDate AS DATE) AS FoundingDate, CAST(AddressLine1 AS TEXT) AS AddressLine1, CAST(AddressLine2 AS TEXT) AS AddressLine2, CAST(PostalCode AS TEXT) AS PostalCode, CAST(City AS TEXT) AS City, CAST(StateProv AS TEXT) AS StateProv, CAST(Country AS TEXT) AS Country, CAST(CASE WHEN LEAD(EffectiveDate) OVER (PARTITION BY CompanyID ORDER BY EffectiveDate ASC) IS NULL THEN TRUE ELSE FALSE END AS BOOLEAN) AS IsCurrent, CAST(1 AS DECIMAL(5, 0)) AS BatchID, CAST(EffectiveDate AS DATE) AS EffectiveDate, CAST(COALESCE(LEAD(EffectiveDate) OVER (PARTITION BY CompanyID ORDER BY EffectiveDate ASC), CAST('9999-12-31' AS DATE)) AS DATE) AS EndDate FROM (SELECT CIK AS CompanyID, CompanyName AS Name, SPrating, CEOname AS CEO, Description, TRY_CAST(NULLIF(CMP.FoundingDate, '') AS DATE) AS FoundingDate, AddrLine1 AS AddressLine1, AddrLine2 AS AddressLine2, PostalCode, City, StateProvince AS StateProv, Country, S.ST_NAME AS Status, I.IN_NAME AS Industry, (CASE WHEN SPrating LIKE 'A%' OR SPrating LIKE 'BBB%' THEN FALSE ELSE TRUE END) AS isLowGrade, STRPTIME(PTS, '%Y%m%d-%H%M%S') AS EffectiveDate FROM Source.FinwireCMP AS CMP, Source.StatusType AS S, Source.Industry AS I WHERE CMP.Status = S.ST_ID AND CMP.IndustryID = I.IN_ID) AS c;
